    "parentId": 1400332,
    "start": 1435.04,
    "end": 1437.44,
    "speaker": "Kero",
    "text": "Auf die Idee, Kostüme für Sakura zu entwerfen,",
    "vi": "Ý tưởng thiết kế trang phục chiến đấu cho Sakura",
